//! **A composable `FederationDirectory` double (CIRISPersist#603/#604).**
//!
//! GENERATED by `scripts/gen_directory_double.py`. Do not edit by hand —
//! edit the generator. `scripts/gen_directory_double.py --check` fails if this
//! file is stale.
//!
//! # The arm nobody could reach
//!
//! `resolve_mesh_config` folds per-root reads and carries `unreadable_roots`,
//! so *"this backend cannot answer for root R"* and *"root R said nothing"* stay
//! distinct. **No test in this repo could reach that arm**: all three shipped
//! backends implement every method, so none can return `Error::Unsupported`.
//! The only party exercising it was CIRISServer, through their own directory
//! impl — which is how the defect was found in the first place (#603).
//!
//! #604 recorded the pattern across five workstreams in one week:
//!
//! ```text
//! Ok(value)  -> a real answer
//! Ok(empty)  -> a real answer that happens to be empty
//! Err(_)     -> WE COULD NOT ASK
//! ```
//!
//! Collapsing that third arm is how a zero becomes evidence it has not earned.
//! The Constitution's own discipline: **a zero is not evidence unless the
//! instrument can fail.** This is the instrument that can fail.
//!
//! # Shape
//!
//! It WRAPS a real directory rather than stubbing 162 methods, so every
//! un-faulted call keeps real behaviour and a fixture only declares the
//! divergence it cares about.
//!
//! ```ignore
//! let dbl = FaultInjectingDirectory::new(backend)
//!     .unsupported("list_attestations_for");
//! // every other method behaves exactly as `backend` does
//! ```
//!
//! Test-only: `#[cfg(any(test, feature = "test-anchor"))]`, and `pub` because
//! CIRISServer/Edge/Agent need it (#664 was the same wall one module over).

// A glob import on purpose: this file delegates EVERY trait signature, so it
// needs the trait's whole type scope. Naming them individually would be a
// second list to keep in sync with the first — the exact failure this
// generator exists to remove.
#[allow(unused_imports)]
use super::*;
use std::collections::BTreeSet;
use std::sync::Arc;

/// A `FederationDirectory` that delegates to `inner`, except where a method
/// has been declared faulted — there it returns [`Error::Unsupported`].
///
/// Cloneable and `Send + Sync`, so it drops into any fixture that takes a
/// directory. The fault set is by METHOD NAME, matching the `method` field
/// `Error::Unsupported` already carries, so a refusal names the same thing the
/// fixture declared.
#[derive(Clone)]
pub struct FaultInjectingDirectory {
    inner: Arc<dyn FederationDirectory>,
    unsupported: BTreeSet<&'static str>,
    erroring: BTreeSet<&'static str>,
}

impl std::fmt::Debug for FaultInjectingDirectory {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("FaultInjectingDirectory")
            .field("unsupported", &self.unsupported)
            .field("erroring", &self.erroring)
            .finish_non_exhaustive()
    }
}

impl FaultInjectingDirectory {
    /// Wrap a real directory. With no faults declared it is behaviourally
    /// identical to `inner` — a fixture opts INTO each divergence.
    #[must_use]
    pub fn new(inner: Arc<dyn FederationDirectory>) -> Self {
        Self {
            inner,
            unsupported: BTreeSet::new(),
            erroring: BTreeSet::new(),
        }
    }

    /// Declare that `method` answers `Error::Unsupported { method }`.
    ///
    /// The name is NOT validated against the trait: an unknown name is inert
    /// rather than an error, because a fixture written against a newer persist
    /// should degrade to *"that fault did not fire"* and fail on its own
    /// assertion, not panic inside the double. Use [`Self::faults`] to assert
    /// what was actually declared.
    #[must_use]
    pub fn unsupported(mut self, method: &'static str) -> Self {
        self.unsupported.insert(method);
        self
    }

    /// The declared fault set — so a fixture can assert its own setup.
    #[must_use]
    pub fn faults(&self) -> &BTreeSet<&'static str> {
        &self.unsupported
    }

    /// v36.0.0 (CIRISPersist#624) — declare that `method` answers a
    /// GENERIC backend failure, not `Unsupported`.
    ///
    /// The two kinds are not interchangeable: `Unsupported` means *this
    /// directory cannot answer*, which several trait defaults treat as a
    /// sanctioned degrade-to-plan-free path. `Backend` means *the answer
    /// was attempted and FAILED*, which must propagate. Without this
    /// second kind a mutation collapsing a typed `Unsupported` arm into
    /// `Err(_)` survives every witness — measured on #624 (M6).
    #[must_use]
    pub fn erroring(mut self, method: &'static str) -> Self {
        self.erroring.insert(method);
        self
    }

    /// The declared generic-failure set — so a fixture can assert setup.
    #[must_use]
    pub fn error_faults(&self) -> &BTreeSet<&'static str> {
        &self.erroring
    }

    fn faulted(&self, method: &'static str) -> Option<Error> {
        if self.unsupported.contains(method) {
            return Some(Error::Unsupported { method });
        }
        self.erroring
            .contains(method)
            .then(|| Error::Backend(format!("injected backend failure: {method}")))
    }
}

